A,WAAA;IACA,aAAA;ECXd;EDgBM;IACI,eAAA;ECdV;AACF;ADoBA;EACI,mBG7NS;AF2Mb;;AG9MA;EACE,aAAA;EACA,sBAAA;EACA,QAAA;AHiNF","file":"profileFavorites.css","sourcesContent":[".advertisement__list {\r\n    flex: 1 1 680px;\r\n}\r\n\r\n.default__item {\r\n    & .advertisement__list-item {\r\n        display: flex;\r\n        gap: 40px;\r\n        padding: 5px;\r\n        border-bottom: 1px solid $gray;\r\n    }\r\n\r\n    & ~.vip__wrap {\r\n        flex: 1 0 250px;\r\n    }\r\n    \r\n    & .advertisement__list-item-img {\r\n        display: block;\r\n        max-width: 180px;\r\n        max-height: 140px;\r\n        & img {\r\n            width: 100%;\r\n            height: 100%;\r\n            object-fit: cover;\r\n            object-position: center;\r\n        }\r\n    }\r\n    \r\n    & .advertisement__list-item-about{\r\n        flex: 1 1 auto;\r\n        display: flex;\r\n        flex-direction: column;\r\n        gap: 10px;\r\n        position: relative;\r\n    }\r\n\r\n    & .advertisement__list-item-about-favorites {\r\n        cursor: pointer;\r\n        display: block;\r\n        width: 18px;\r\n        height: 18px;\r\n        background: url(../img/favorite.png) no-repeat center/cover;\r\n        position: absolute;\r\n        bottom: 0;\r\n        right: 0;\r\n    }\r\n    \r\n    & .advertisement__list-item-title {\r\n        & a {\r\n            @include fonts($mainColor, 18px, 400);\r\n            overflow: hidden;\r\n            display: -webkit-box;\r\n            -webkit-line-clamp: 1;\r\n            -webkit-box-orient: vertical;\r\n            &:hover {\r\n                color: $colorHover;\r\n            }\r\n        }\r\n    }\r\n    \r\n    & .advertisement__list-item-price {\r\n        @include fonts($defaultColor, 16px, 400);\r\n    }\r\n    \r\n    & .advertisement__list-item-about-text-list {\r\n        & li {\r\n            @include fonts(gray, 16px, 400);\r\n        }\r\n    }\r\n    \r\n    & .advertisement__list-item-action {\r\n        display: flex;\r\n        align-items: center;\r\n        gap: 10px;\r\n        align-self: flex-end;\r\n    \r\n    \r\n        & li {\r\n            max-width: 18px;\r\n            max-height: 18px;\r\n            & img {\r\n                width: 100%;\r\n                height: 100%;\r\n                object-fit: cover;\r\n                object-position: center;\r\n            }\r\n        }\r\n    }\r\n    & .advertisement__favorites-active {\r\n        background: url(../img/favorite_yes.png) no-repeat center/cover;\r\n    }\r\n}\r\n.second__item {\r\n    display: grid;\r\n    grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));\r\n    gap: 10px 15px;\r\n    flex: 1 1 auto;\r\n    & .advertisement__list-item {\r\n        display: flex;\r\n        flex-direction: column;\r\n        height: 100%;\r\n        justify-content: space-between;\r\n        gap: 10px;\r\n        padding: 8px;\r\n        border: 1px solid $gray;\r\n        border-radius: 7px;\r\n    }\r\n\r\n    & ~.vip__wrap {\r\n        flex: 0 0 250px;\r\n    }\r\n    \r\n\r\n    & .advertisement__list-item-img {\r\n        display: block;\r\n        flex: 0 1 140px;\r\n        & img {\r\n            max-height: 140px;\r\n            width: 100%;\r\n            height: 100%;\r\n            object-fit: cover;\r\n            object-position: center;\r\n        }\r\n    }\r\n\r\n    & .advertisement__list-item-title {\r\n        & a {\r\n            display: block;\r\n            overflow: hidden;\r\n            white-space: nowrap;\r\n            text-overflow: ellipsis;\r\n            max-width: 180px;\r\n            @include fonts($mainColor, 16px, 400);\r\n            &:hover {\r\n                color: $colorHover;\r\n            }\r\n        }\r\n    }\r\n\r\n    & .advertisement__list-item-price {\r\n        @include fonts(gray, 14px, 400);\r\n        margin: 5px 0;\r\n    }\r\n\r\n    & .advertisement__list-item-about-text-list {\r\n        display: flex;\r\n        flex-direction: column;\r\n        gap: 5px;\r\n\r\n        & li {\r\n            @include fonts(gray, 14px, 400);\r\n            &:nth-child(1) {\r\n                display: none;\r\n            }\r\n            \r\n            &:nth-child(2) {\r\n                display: none;\r\n            }\r\n        }\r\n    }\r\n\r\n    & .advertisement__list-item-action{\r\n        display: none;\r\n    }\r\n\r\n    & .advertisement__list-item-about {\r\n        position: relative;\r\n    }\r\n\r\n    & .advertisement__list-item-about-favorites {\r\n        cursor: pointer;\r\n        display: block;\r\n        width: 18px;\r\n        height: 18px;\r\n        background: url(../img/favorite.png) no-repeat center/cover;\r\n        position: absolute;\r\n        bottom: 0;\r\n        right: 0;\r\n    }\r\n\r\n    & .advertisement__favorites-active {\r\n        background: url(../img/favorite_yes.png) no-repeat center/cover;\r\n    }\r\n}\r\n\r\n\r\n\r\n\r\n@media (max-width: 992px) {\r\n\r\n    .default__item{\r\n        flex: 1 1 auto;\r\n        & ~.vip__wrap {\r\n            flex: 1 0 250px;\r\n        }\r\n\r\n        & .advertisement__list-item {\r\n            gap: 15px;\r\n            flex-direction: column;\r\n        }\r\n\r\n        & .advertisement__list-item-img {\r\n            max-width: none;\r\n            max-height: none;\r\n            & img {\r\n                max-height: 400px;\r\n            }\r\n        }\r\n\r\n        & .advertisement__list-item-about {\r\n            &::before {\r\n                top: initial;\r\n                bottom: 0;\r\n                right: 10px;\r\n                left: initial;\r\n            }\r\n        }\r\n    }\r\n    .second__item {\r\n        & ~.vip__wrap {\r\n            flex: 1 0 250px;\r\n        }\r\n    }\r\n}\r\n\r\n\r\n\r\n.active__item {\r\n    background: $activeItem;\r\n}",".advertisement__list {\n  flex: 1 1 680px;\n}\n\n.default__item .advertisement__list-item {\n  display: flex;\n  gap: 40px;\n  padding: 5px;\n  border-bottom: 1px solid #D4D4D4;\n}\n.default__item ~ .vip__wrap {\n  flex: 1 0 250px;\n}\n.default__item .advertisement__list-item-img {\n  display: block;\n  max-width: 180px;\n  max-height: 140px;\n}\n.default__item .advertisement__list-item-img img {\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n  object-position: center;\n}\n.default__item .advertisement__list-item-about {\n  flex: 1 1 auto;\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n  position: relative;\n}\n.default__item .advertisement__list-item-about-favorites {\n  cursor: pointer;\n  display: block;\n  width: 18px;\n  height: 18px;\n  background: url(../img/favorite.png) no-repeat center/cover;\n  position: absolute;\n  bottom: 0;\n  right: 0;\n}\n.default__item .advertisement__list-item-title a {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: #3077a0;\n  font-size: 18px;\n  overflow: hidden;\n  display: -webkit-box;\n  -webkit-line-clamp: 1;\n  -webkit-box-orient: vertical;\n}\n.default__item .advertisement__list-item-title a:hover {\n  color: red;\n}\n.default__item .advertisement__list-item-price {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 16px;\n}\n.default__item .advertisement__list-item-about-text-list li {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: gray;\n  font-size: 16px;\n}\n.default__item .advertisement__list-item-action {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  align-self: flex-end;\n}\n.default__item .advertisement__list-item-action li {\n  max-width: 18px;\n  max-height: 18px;\n}\n.default__item .advertisement__list-item-action li img {\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n  object-position: center;\n}\n.default__item .advertisement__favorites-active {\n  background: url(../img/favorite_yes.png) no-repeat center/cover;\n}\n\n.second__item {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));\n  gap: 10px 15px;\n  flex: 1 1 auto;\n}\n.second__item .advertisement__list-item {\n  display: flex;\n  flex-direction: column;\n  height: 100%;\n  justify-content: space-between;\n  gap: 10px;\n  padding: 8px;\n  border: 1px solid #D4D4D4;\n  border-radius: 7px;\n}\n.second__item ~ .vip__wrap {\n  flex: 0 0 250px;\n}\n.second__item .advertisement__list-item-img {\n  display: block;\n  flex: 0 1 140px;\n}\n.second__item .advertisement__list-item-img img {\n  max-height: 140px;\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n  object-position: center;\n}\n.second__item .advertisement__list-item-title a {\n  display: block;\n  overflow: hidden;\n  white-space: nowrap;\n  text-overflow: ellipsis;\n  max-width: 180px;\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: #3077a0;\n  font-size: 16px;\n}\n.second__item .advertisement__list-item-title a:hover {\n  color: red;\n}\n.second__item .advertisement__list-item-price {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: gray;\n  font-size: 14px;\n  margin: 5px 0;\n}\n.second__item .advertisement__list-item-about-text-list {\n  display: flex;\n  flex-direction: column;\n  gap: 5px;\n}\n.second__item .advertisement__list-item-about-text-list li {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: gray;\n  font-size: 14px;\n}\n.second__item .advertisement__list-item-about-text-list li:nth-child(1) {\n  display: none;\n}\n.second__item .advertisement__list-item-about-text-list li:nth-child(2) {\n  display: none;\n}\n.second__item .advertisement__list-item-action {\n  display: none;\n}\n.second__item .advertisement__list-item-about {\n  position: relative;\n}\n.second__item .advertisement__list-item-about-favorites {\n  cursor: pointer;\n  display: block;\n  width: 18px;\n  height: 18px;\n  background: url(../img/favorite.png) no-repeat center/cover;\n  position: absolute;\n  bottom: 0;\n  right: 0;\n}\n.second__item .advertisement__favorites-active {\n  background: url(../img/favorite_yes.png) no-repeat center/cover;\n}\n\n@media (max-width: 992px) {\n  .default__item {\n    flex: 1 1 auto;\n  }\n  .default__item ~ .vip__wrap {\n    flex: 1 0 250px;\n  }\n  .default__item .advertisement__list-item {\n    gap: 15px;\n    flex-direction: column;\n  }\n  .default__item .advertisement__list-item-img {\n    max-width: none;\n    max-height: none;\n  }\n  .default__item .advertisement__list-item-img img {\n    max-height: 400px;\n  }\n  .default__item .advertisement__list-item-about::before {\n    top: initial;\n    bottom: 0;\n    right: 10px;\n    left: initial;\n  }\n  .second__item ~ .vip__wrap {\n    flex: 1 0 250px;\n  }\n}\n.active__item {\n  background: #FFFFCA;\n}\n\n.main__info-favorites-list {\n  display: flex;\n  flex-direction: column;\n  gap: 5px;\n}","@mixin fonts($color,$size,$weight) {\r\n    font-family: 'Trebuchet MS', sans-serif;\r\n    font-weight: $weight;\r\n    font-style: normal;\r\n    color: $color;\r\n    font-size: $size;\r\n}","$mainColor: #3077a0;\r\n$defaultColor: black;\r\n$colorHover: red;\r\n$headerTopBorder: #bdd4e2;\r\n$buttonBg:linear-gradient(0deg, #4d95d6,#6e93dd,#c2d6f4);;\r\n$gray: #D4D4D4;\r\n$vipBg: #ff6163;\r\n$activeItem: #FFFFCA;\r\n$userSearchBg: #CFE6FE;\r\n$asideLinksColor: #307792;\r\n$asideExitColor: rgb(0, 128, 0);","@import \"./variables\";\r\n@import \"./mixins\";\r\n@import \"./advertisementItem\";\r\n\r\n.main__info-favorites-list {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 5px;\r\n}"]}splay: flex;\r\n  flex-direction: column;\r\n  gap: 5px;\r\n}"]}